import { test, expect, type Page } from "@playwright/test";
import { measure } from "../scripts/mobile-audit";
import { isTradingDay } from "../lib/market-calendar";

/**
 * The FII/DII page on a phone, against a mocked /api/fiidii serving rows shaped like the stored NSE data. No database is needed and
 * nothing here is generated by the page: with no rows it must say "Data not available yet", and it must never show the old
 * "Simulated data" / "illustrative" labels while real data is showing.
 */
test.use({
  viewport: { width: 360, height: 800 },
  isMobile: true,
  hasTouch: true,
  userAgent: "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Mobile Safari/537.36",
});

test.beforeEach(async ({ page }) => {
  await page.addInitScript("window.__name = function (f) { return f; };");
});

interface Row {
  date: string;
  cash: { fii: { buy: number; sell: number; net: number }; dii: { buy: number; sell: number; net: number } } | null;
  idxFut: { long: number; short: number } | null;
  provisional: boolean;
}

const addDays = (d: string, n: number) => new Date(Date.parse(`${d}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10);

/** One row per trading day from `from` to `to`, with cash figures and futures positions that vary day to day. */
function fixture(from: string, to: string, skip: string[] = []): Row[] {
  const out: Row[] = [];
  let i = 0;
  for (let d = from; d <= to; d = addDays(d, 1)) {
    if (!isTradingDay(d) || skip.includes(d)) continue;
    i++;
    const fiiNet = Math.round(((i % 7) - 3) * 1450.37 * 100) / 100;
    const diiNet = Math.round(((i % 5) - 2) * 1120.11 * 100) / 100;
    out.push({
      date: d,
      cash: {
        fii: { buy: 20000 + Math.max(fiiNet, 0), sell: 20000 + Math.max(-fiiNet, 0), net: fiiNet },
        dii: { buy: 15000 + Math.max(diiNet, 0), sell: 15000 + Math.max(-diiNet, 0), net: diiNet },
      },
      idxFut: { long: 50000 + i * 1300, short: 120000 - i * 900 },
      provisional: true,
    });
  }
  return out;
}

async function mock(page: Page, body: unknown, status = 200) {
  await page.route("**/api/fiidii", (route) => route.fulfill({ status, json: body }));
}

async function open(page: Page) {
  await page.goto("/app/fiidii", { waitUntil: "domcontentloaded" });
  await page.waitForSelector("h2", { timeout: 30_000 });
  await page.waitForTimeout(800);
}

// 5 Oct to 6 Nov 2026: more than twenty trading days, none of them a special session
const FULL = fixture("2026-10-05", "2026-11-06");

test("real data: the data date and the word provisional are shown, and the old simulated labels are gone", async ({ page }) => {
  await mock(page, { status: "ok", rows: FULL });
  await open(page);
  await expect(page.getByTestId("data-date")).toContainText("Data for 06 Nov 2026");
  await expect(page.getByTestId("data-date")).toContainText("provisional");
  const body = await page.locator("body").innerText();
  expect(body).not.toMatch(/illustrative/i);
  expect(body).not.toContain("Simulated data");
  expect(body).not.toContain("Data not available yet");
  expect(FULL.length, "enough days that the history-building note is not shown").toBeGreaterThanOrEqual(20);
  await expect(page.getByTestId("history-building")).toHaveCount(0);
});

test("no data stored yet: 'Data not available yet', and nothing invented in its place", async ({ page }) => {
  await mock(page, { status: "empty", rows: [] });
  await open(page);
  await expect(page.getByTestId("no-data")).toHaveText("Data not available yet");
  const body = await page.locator("body").innerText();
  expect(body).not.toMatch(/₹[\d,]+ Cr/);
  expect(await page.locator("table, svg[role=img]").count()).toBe(0);
});

test("the data store being unreachable also says 'Data not available yet'", async ({ page }) => {
  await mock(page, { status: "unavailable", rows: [] });
  await open(page);
  await expect(page.getByTestId("no-data")).toBeVisible();
});

test("a failed request says 'Data not available yet' too", async ({ page }) => {
  await mock(page, { error: "boom" }, 500);
  await open(page);
  await expect(page.getByTestId("no-data")).toBeVisible();
});

test("history is building: a few days stored say so, and do not pretend there is more", async ({ page }) => {
  await mock(page, { status: "ok", rows: fixture("2026-11-04", "2026-11-06") });
  await open(page);
  const note = page.getByTestId("history-building");
  await expect(note).toContainText("History is building");
  await expect(note).toContainText("3 days of cash figures are stored so far");
  expect(await page.locator("table tbody tr").count()).toBe(3);
});

test("FII/DII: the whole Net amount is visible on every row", async ({ page }) => {
  await mock(page, { status: "ok", rows: FULL });
  await open(page);
  expect(await page.locator("table tbody tr").count()).toBeGreaterThan(5);
  const bad = await page.evaluate(() => {
    const out: string[] = [];
    document.querySelectorAll("table tbody tr").forEach((tr, i) => {
      const cell = tr.lastElementChild as HTMLElement;
      const r = cell.getBoundingClientRect();
      if (r.right > window.innerWidth + 0.5 || r.left < 0 || cell.scrollWidth > cell.clientWidth + 1) out.push(`row ${i}: ${cell.innerText} right=${Math.round(r.right)}`);
    });
    return out;
  });
  expect(bad).toEqual([]);
});

test("FII/DII: amounts put the sign before the rupee sign", async ({ page }) => {
  await mock(page, { status: "ok", rows: FULL });
  await open(page);
  const text = await page.locator("table tbody").innerText();
  expect(text).toMatch(/[+−]₹[\d,]+ Cr/);
  expect(text).not.toMatch(/₹[+\-−]/);
});

test("FII/DII: the chart shows the same date range as the table", async ({ page }) => {
  await mock(page, { status: "ok", rows: FULL });
  await open(page);
  const caption = await page.locator("p.tabular-nums, span.tabular-nums").filter({ hasText: /–/ }).first().innerText();
  const bars = await page.locator("svg[role=img] rect[fill='#047857'], svg[role=img] rect[fill='#be123c']").count();
  const rows = await page.locator("table tbody tr").count();
  expect(caption).toMatch(/\d/);
  expect(bars).toBe(rows);
});

test("a trading day with no stored figures is a gap: 'Data not available', no zero amount, no bar", async ({ page }) => {
  await mock(page, { status: "ok", rows: fixture("2026-10-12", "2026-11-06", ["2026-10-28"]) });
  await open(page);
  const gap = page.locator('table tbody tr[data-missing="true"]');
  await expect(gap).toHaveCount(1);
  await expect(gap).toContainText("28 Oct");
  await expect(gap).toContainText("Data not available");
  expect(await gap.innerText()).not.toMatch(/₹/);
  expect(await page.locator("svg[role=img] g[data-missing='true']").count()).toBe(1);
  const bars = await page.locator("svg[role=img] rect[fill='#047857'], svg[role=img] rect[fill='#be123c']").count();
  expect(bars, "one bar for every row that has data").toBe((await page.locator("table tbody tr").count()) - 1);
});

test("weekly and monthly roll-ups say how many trading days each period covers", async ({ page }) => {
  await mock(page, { status: "ok", rows: fixture("2026-10-14", "2026-11-06") }); // starts on a Wednesday: the first week is partial
  await open(page);
  await page.getByLabel("Interval").selectOption("weekly");
  await page.waitForTimeout(300);
  const first = page.locator("table tbody tr").last();
  await expect(first).toContainText("trading days");
  expect(await page.locator("table thead").innerText()).toContain("Week of");
  await page.getByLabel("Interval").selectOption("monthly");
  await page.waitForTimeout(300);
  expect(await page.locator("table thead").innerText()).toContain("Month");
  expect(await page.locator("table tbody tr").count()).toBe(2);
});

test("FII index futures: long % against short %, from the stored positions", async ({ page }) => {
  await mock(page, { status: "ok", rows: FULL });
  await open(page);
  const section = page.locator("h3", { hasText: "long % against short %" }).locator("..");
  await expect(section).toContainText("Long");
  await expect(section).toContainText("Short");
  expect(await section.locator("[role=img]").count()).toBeGreaterThan(3);
  expect(await section.innerText()).toMatch(/Long \d+\.\d%/);
});

test("with data showing, the page does not scroll sideways at 360px", async ({ page }) => {
  await mock(page, { status: "ok", rows: FULL });
  await open(page);
  const m = (await page.evaluate(measure)) as { pageScroll: number; wide: string[]; clipped: string[]; tableOverflow: string[] };
  expect(m.pageScroll).toBeLessThanOrEqual(1);
  expect(m.wide).toEqual([]);
  expect(m.tableOverflow).toEqual([]);
});
